sealed interface Forme permits Cercle, Rectangle, Triangle { }
record Cercle(double rayon) implements Forme { }
record Rectangle(double largeur, double hauteur) implements Forme { }
record Triangle(double base, double hauteur) implements Forme { }

static double aire(Forme forme) {
    return switch (forme) {
        // Chaque cas deconstruit le record et lit ses composants.
        case Cercle(var rayon)            -> Math.PI * rayon * rayon;
        case Rectangle(var l, var h)      -> l * h;
        case Triangle(var base, var h)    -> (base * h) / 2;
        // Pas de default : sealed garantit que tous les cas sont couverts.
    };
}

sealed interface Evenement permits Connexion, Message, Deconnexion { }
record Connexion(String utilisateur) implements Evenement { }
record Message(String utilisateur, String texte) implements Evenement { }
record Deconnexion(String utilisateur) implements Evenement { }

static String journaliser(Evenement e) {
    return switch (e) {
        case Connexion(var user)          -> user + " s'est connecte";
        case Message(var user, var texte) -> user + " dit : " + texte;
        case Deconnexion(var user)        -> user + " est parti";
    };
}

sections.solution:
static double perimetre(Forme f) {
    return switch (f) {
        case Cercle(var rayon) -> 2 * Math.PI * rayon;
        case Carre(var cote)   -> 4 * cote;
    };
}

Comme Forme est sealed et ne permet que Cercle et Carre, le switch est exhaustif : pas besoin de default, et si on ajoute une forme plus tard sans traiter son cas, le compilateur refusera de compiler. Chaque cas deconstruit le record pour lire son unique composant.
